Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "config": {
    "view": {
      "stroke": null
    },
    "background": "transparent",
    "font": "Segoe UI"
  },
  "title": {
    "text": "Confiabilidade × resposta: cada ponto é um mês de uma planta",
    "color": "#7A8B99",
    "anchor": "start",
    "fontSize": 12,
    "fontWeight": "normal",
    "font": "Segoe UI Semibold",
    "offset": 10
  },
  "width": "container",
  "height": "container",
  "layer": [
    {
      "mark": {
        "type": "rule",
        "color": "#2FBF71",
        "strokeDash": [
          4,
          4
        ],
        "opacity": 0.8
      },
      "encoding": {
        "y": {
          "datum": 300
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "color": "#2FBF71",
        "align": "left",
        "dx": 4,
        "dy": -8,
        "fontSize": 10
      },
      "encoding": {
        "y": {
          "datum": 300
        },
        "x": {
          "datum": 1.0
        },
        "text": {
          "value": "Meta MTBF > 300 h"
        }
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#E5484D",
        "strokeDash": [
          4,
          4
        ],
        "opacity": 0.8
      },
      "encoding": {
        "x": {
          "datum": 2.5
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "color": "#E5484D",
        "align": "left",
        "dx": 4,
        "fontSize": 10
      },
      "encoding": {
        "x": {
          "datum": 2.5
        },
        "y": {
          "datum": 120
        },
        "text": {
          "value": "Meta MTTR < 2,5 h"
        }
      }
    },
    {
      "mark": {
        "type": "circle",
        "size": 60,
        "opacity": 0.85,
        "stroke": "#232B32",
        "strokeWidth": 1
      },
      "encoding": {
        "x": {
          "field": "MTTR",
          "type": "quantitative",
          "scale": {
            "domain": [
              1,
              3
            ]
          },
          "axis": {
            "labelColor": "#7A8B99",
            "labelFont": "Segoe UI",
            "labelFontSize": 10,
            "domain": false,
            "ticks": false,
            "title": "MTTR (h) — tempo médio de reparo",
            "titleColor": "#7A8B99",
            "titleFontWeight": "normal",
            "grid": true,
            "gridColor": "#3A4651",
            "gridDash": [
              2,
              3
            ]
          }
        },
        "y": {
          "field": "MTBF",
          "type": "quantitative",
          "scale": {
            "type": "log",
            "domain": [
              20,
              400
            ]
          },
          "axis": {
            "labelColor": "#7A8B99",
            "labelFont": "Segoe UI",
            "labelFontSize": 10,
            "domain": false,
            "ticks": false,
            "title": "MTBF (h) — escala log",
            "titleColor": "#7A8B99",
            "titleFontWeight": "normal",
            "grid": true,
            "gridColor": "#3A4651",
            "gridDash": [
              2,
              3
            ],
            "values": [
              20,
              50,
              100,
              200,
              300,
              400
            ]
          }
        },
        "color": {
          "field": "Planta",
          "type": "nominal",
          "scale": {
            "domain": [
              "Campinas",
              "Joinville",
              "Manaus"
            ],
            "range": [
              "#C9D3DB",
              "#FF8C00",
              "#7A8B99"
            ]
          },
          "legend": {
            "orient": "top",
            "title": null,
            "labelColor": "#7A8B99"
          }
        },
        "tooltip": [
          {
            "field": "Planta"
          },
          {
            "field": "Mes",
            "type": "temporal",
            "format": "%b/%Y",
            "title": "Mês"
          },
          {
            "field": "MTBF",
            "format": ".1f",
            "title": "MTBF (h)"
          },
          {
            "field": "MTTR",
            "format": ".2f",
            "title": "MTTR (h)"
          }
        ]
      }
    }
  ]
}'
